script:
test("partial hour rounds up to three billable hours", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-10 10:01"
  }), {
    status: "ok",
    elapsedMinutes: 121,
    roundedHours: 3,
    billableHours: 3,
    flags: []
  });
});

test("spring forward real time is twenty three hours not twenty four", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-03-07 22:00",
    discharge: "2026-03-08 22:00"
  }), {
    status: "ok",
    elapsedMinutes: 1380,
    roundedHours: 23,
    billableHours: 23,
    flags: []
  });
});

test("fall back real time is twenty five hours not twenty four", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-10-31 22:00",
    discharge: "2026-11-01 22:00"
  }), {
    status: "ok",
    elapsedMinutes: 1500,
    roundedHours: 25,
    billableHours: 25,
    flags: []
  });
});

test("seventy two real hours is capped at forty eight billable hours", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-13 08:00"
  }), {
    status: "ok",
    elapsedMinutes: 4320,
    roundedHours: 72,
    billableHours: 48,
    flags: []
  });
});

test("equal admission and discharge is valid and stays zero hours", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-01-31 19:47",
    discharge: "2026-01-31 19:47"
  }), {
    status: "ok",
    elapsedMinutes: 0,
    roundedHours: 0,
    billableHours: 0,
    flags: []
  });
});

test("one minute onto leap day rounds up to one billable hour", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2024-02-28 23:59",
    discharge: "2024-02-29 00:00"
  }), {
    status: "ok",
    elapsedMinutes: 1,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("twenty nine minutes below halfway rounds up to one hour", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-12-31 23:31",
    discharge: "2027-01-01 00:00"
  }), {
    status: "ok",
    elapsedMinutes: 29,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("thirty minutes halfway rounds up and two oclock after fallback is not ambiguous", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-11-01 02:00",
    discharge: "2026-11-01 02:30"
  }), {
    status: "ok",
    elapsedMinutes: 30,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("thirty one minutes rounds up and one fifty nine before the spring gap exists", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-03-08 01:28",
    discharge: "2026-03-08 01:59"
  }), {
    status: "ok",
    elapsedMinutes: 31,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("exactly forty eight real hours is billed as forty eight", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-03-08 03:00",
    discharge: "2026-03-10 03:00"
  }), {
    status: "ok",
    elapsedMinutes: 2880,
    roundedHours: 48,
    billableHours: 48,
    flags: []
  });
});

test("one minute below forty eight hours rounds up to forty eight", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-01-20 11:05",
    discharge: "2026-01-22 11:04"
  }), {
    status: "ok",
    elapsedMinutes: 2879,
    roundedHours: 48,
    billableHours: 48,
    flags: []
  });
});

test("one minute above forty eight hours rounds to forty nine then caps at forty eight", function () {
  assert.deepEqual(code.billableObservationHours({
    admission: "2026-01-20 11:05",
    discharge: "2026-01-22 11:06"
  }), {
    status: "ok",
    elapsedMinutes: 2881,
    roundedHours: 49,
    billableHours: 48,
    flags: []
  });
});

test("ambiguous admission time is flagged and no hours are computed", function () {
  var actual = code.billableObservationHours({
    admission: "2026-11-01 01:00",
    discharge: "2026-11-01 12:00"
  });
  assert.equal(actual.status, "ambiguous");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /admission/);
});

test("nonexistent discharge time is flagged and no hours are computed", function () {
  var actual = code.billableObservationHours({
    admission: "2026-03-08 01:00",
    discharge: "2026-03-08 02:00"
  });
  assert.equal(actual.status, "nonexistent");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /discharge/);
});

test("discharge earlier than admission is invalid and no hours are computed", function () {
  var actual = code.billableObservationHours({
    admission: "2026-07-04 00:00",
    discharge: "2026-07-03 23:59"
  });
  assert.equal(actual.status, "invalid");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /discharge/);
});

test("unknown field throws an error naming that field", function () {
  assert.throws(function () {
    code.billableObservationHours({
      admission: "2026-06-18 14:22",
      discharge: "2026-06-18 16:22",
      priority: "stat"
    });
  }, /^unknown field: priority$/);
});
